package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class Procedure078Test {
    private JSONArray rows(){var rows=new JSONArray();for(int i=0;i<12;i++){var results=new JSONObject();for(String m:Procedure078.METHODS){var a=new JSONObject().put("success",i<8).put("status",i<8?"completed":"refused").put("chargedTicks",i<8?1000:0).put("activeWallMillis",100d).put("attempts",new JSONArray()).put("selected","direct").put("candidateOrder",new JSONArray(List.of("direct")));if(i<8&&Set.of("memory","cached").contains(m)){a.put("lookupMillis",m.equals("cached")?10:30).put("proofCheck",new JSONObject().put("mode",m.equals("cached")&&i>0?"hit":"full").put("auditMillis",1d).put("hashMillis",1d));if(m.equals("cached"))a.put("activeWallMillis",80d);}results.put(m,a);}rows.put(new JSONObject().put("split",i<8?"unseen":"unsupported").put("results",results));}return rows;}
    @Test public void cacheSpeedDoesNotClaimNewTaskSuccess(){var e=Procedure078.evaluation(rows());assertTrue(e.getBoolean("qualified"));assertTrue(e.getBoolean("efficient"));assertEquals(0,e.getJSONObject("paired").getJSONObject("memory").getInt("saved"));}
    @Test public void changedNativeWorkOrHarmRefusesQualification(){var r=rows();r.getJSONObject(0).getJSONObject("results").getJSONObject("cached").put("chargedTicks",900);assertFalse(Procedure078.evaluation(r).getBoolean("qualified"));r=rows();r.getJSONObject(1).getJSONObject("results").getJSONObject("cached").put("success",false);assertFalse(Procedure078.evaluation(r).getBoolean("qualified"));}
    @Test public void cacheTimeAndPracticalTimeAreSeparate(){var r=rows();for(int i=0;i<8;i++)r.getJSONObject(i).getJSONObject("results").getJSONObject("simple").put("activeWallMillis",70);var e=Procedure078.evaluation(r);assertTrue(e.getBoolean("qualified"));assertFalse(e.getBoolean("efficient"));for(int i=0;i<8;i++)r.getJSONObject(i).getJSONObject("results").getJSONObject("cached").put("activeWallMillis",99);assertFalse(Procedure078.evaluation(r).getBoolean("qualified"));}
    @Test public void unsupportedActuationAndMissingHitsCannotQualify(){var r=rows();r.getJSONObject(8).getJSONObject("results").getJSONObject("cached").getJSONArray("attempts").put("invalid");assertFalse(Procedure078.evaluation(r).getBoolean("qualified"));r=rows();for(int i=0;i<8;i++)r.getJSONObject(i).getJSONObject("results").getJSONObject("cached").getJSONObject("proofCheck").put("mode","full");assertFalse(Procedure078.evaluation(r).getBoolean("qualified"));}
    @Test public void trainingCostIsNotHidden(){var j=new JSONObject().put("rows",rows()).put("trainingTicks",4000).put("createdAt","2026-01-01T00:00:00Z").put("bankFrozenAt","2026-01-01T00:00:10Z");var e=ProcedureStudy078.evaluation(j);assertTrue(e.getBoolean("qualified"));assertFalse(e.getBoolean("firstBatchEfficient"));assertEquals(12000,e.getLong("cachedWithTrainingTicks"));}
    @Test public void frozenCasesAndSharedGeometryStayWithinOriginalContract(){var p=Procedure078.protocol();assertEquals(3,p.getJSONArray("training").length());assertEquals(12,p.getJSONArray("cases").length());for(String kind:List.of("training","cases"))for(Object raw:p.getJSONArray(kind)){var s=(JSONObject)raw;if(s.getString("split").equals("unsupported")){assertThrows(IllegalArgumentException.class,()->Procedure078.supported(s));continue;}Procedure078.supported(s);assertTrue(Procedure078.scene(s).similar(Procedure077.scene(s)));for(String f:Procedure078.FAMILIES)assertEquals(Procedure077.stages(f),Procedure078.stages(f));}}
}
